const ai = $('Ollama').first().json.response;
let d;
try {
  let raw = String(ai || '');
  raw = raw.replace(/```(?:json)?\s*/gi, '').replace(/```\s*/g, '');
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Sin JSON en respuesta');
  d = JSON.parse(m[0]);
} catch (e) {
  throw new Error('JSON invalido de Ollama: ' + e.message + ' | Respuesta: ' + String(ai).substring(0, 200));
}
const gv = (v) => {
  if (v === null || v === undefined) return 'No disponible';
  const s = String(v).trim();
  if (!s || ['null','none','n/a','-','undefined'].includes(s.toLowerCase())) return 'No disponible';
  return s;
};
const fD = (s) => {
  if (s === 'No disponible') return s;
  const clean = s.replace(/[^0-9\-\/\.]/g, '');
  const p = clean.split(/[\-\/\.]/);
  if (p.length < 3) return s;
  let y, mo, dd;
  if (p[0].length === 4) { y=p[0]; mo=p[1]; dd=p[2]; } else { dd=p[0]; mo=p[1]; y=p[2]; }
  if (y.length === 2) y = '20' + y;
  return dd.padStart(2,'0') + '/' + mo.padStart(2,'0') + '/' + y;
};
const toNum = (v) => {
  if (v === null || v === undefined) return 0;
  let s = String(v).replace(/[€$\s]/g,'').trim();
  if (!s) return 0;
  if (s.includes(',') && s.includes('.')) { s = s.replace(/\./g,'').replace(',', '.'); }
  else if (s.includes(',')) { s = s.replace(',', '.'); }
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
};
let numFactura = gv(d.numero_factura);
let fechaFactura = fD(gv(d.fecha_factura));
let fechaVenc = fD(gv(d.fecha_vencimiento));
let codCliente = gv(d.codigo_cliente);
let emisorNombre = gv(d.emisor_nombre);
let emisorCif = gv(d.emisor_cif);
let receptorNombre = (gv(d.receptor_nombre) === 'No disponible') ? 'INNOVATEK' : gv(d.receptor_nombre);
let receptorCif = (gv(d.receptor_cif) === 'No disponible') ? 'E20882726' : gv(d.receptor_cif);
let receptorDir = (gv(d.receptor_direccion) === 'No disponible') ? 'Zaldizurreta 19, Bajo, Beasain, 20200, GIPUZKOA' : gv(d.receptor_direccion);
if (/innovatek|E20882726/i.test(emisorNombre + ' ' + emisorCif)) { emisorNombre='No disponible'; emisorCif='No disponible'; }
let base = toNum(d.base_imponible);
let pctIva = toNum(d.porcentaje_iva);
let cuotaIva = toNum(d.cuota_iva);
let total = toNum(d.total_factura);
if (total === 0 && (base > 0 || cuotaIva > 0)) total = base + cuotaIva;
let formaPago = gv(d.forma_pago);
let iban = gv(d.iban);
if (iban !== 'No disponible') iban = iban.replace(/\s/g,'').toUpperCase();
const esc = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const q = String.fromCharCode(34);
const c = (t,v) => '<ss:Cell><ss:Data ss:Type='+q+t+q+'>'+v+'</ss:Data></ss:Cell>';
let row = '<ss:Row>';
row += c('String', esc(numFactura));
row += c('String', esc(fechaFactura));
row += c('String', esc(fechaVenc));
row += c('String', esc(codCliente));
row += c('String', esc(emisorNombre));
row += c('String', esc(emisorCif));
row += c('String', esc(receptorNombre));
row += c('String', esc(receptorCif));
row += c('String', esc(receptorDir));
row += c('Number', String(base));
row += c('Number', String(pctIva));
row += c('Number', String(cuotaIva));
row += c('Number', String(total));
row += c('String', esc(formaPago));
row += c('String', esc(iban));
row += '</ss:Row>';
let rutaArchivo = 'webhook';
try { const p = $item(0).$node['Separar Archivos'].json.path; if(p) rutaArchivo=p; } catch(e){}
try { const p = $item(0).$node['Extraer Adjuntos Email'].json.savePath; if(p && rutaArchivo==='webhook') rutaArchivo=p; } catch(e){}
let xml = '';
try { const b = await this.helpers.getBinaryDataBuffer(0,'data'); if(b && b.length>0) xml = b.toString('utf-8'); } catch(e){}
const NEW_TOKEN = 'Fecha Vencimiento';
const hasNewSchema = xml.includes(NEW_TOKEN);
if (hasNewSchema && numFactura !== 'No disponible' && xml.includes('>'+esc(numFactura)+'</ss:Data>')) {
  return [{ json: { success: false, reason: 'Duplicate', invoiceNum: numFactura, file: rutaArchivo } }];
}
const re = /(<\/(?:ss:)?Table\s*>)/i;
if (hasNewSchema && re.test(xml)) {
  xml = xml.replace(re, row + '\n$1');
} else {
  const hc = (t) => '<ss:Cell ss:StyleID='+q+'header'+q+'><ss:Data ss:Type='+q+'String'+q+'>'+t+'</ss:Data></ss:Cell>';
  const hdr = '<ss:Row ss:Height='+q+'30'+q+'>'
    + hc('Nº Factura') + hc('Fecha Factura') + hc('Fecha Vencimiento') + hc('Código Cliente')
    + hc('Emisor') + hc('CIF Emisor')
    + hc('Receptor') + hc('CIF Receptor') + hc('Dir Receptor')
    + hc('Base Imponible') + hc('% IVA') + hc('Cuota IVA') + hc('Total')
    + hc('Forma Pago') + hc('IBAN')
    + '</ss:Row>';
  xml = '<?xml version='+q+'1.0'+q+' encoding='+q+'UTF-8'+q+'?>'
      + '<?mso-application progid='+q+'Excel.Sheet'+q+'?>'
      + '<Workbook xmlns='+q+'urn:schemas-microsoft-com:office:spreadsheet'+q+' xmlns:ss='+q+'urn:schemas-microsoft-com:office:spreadsheet'+q+'>'
      + '<Styles>'
      +   '<Style ss:ID='+q+'Default'+q+'><Font ss:FontName='+q+'Calibri'+q+' ss:Size='+q+'11'+q+'/></Style>'
      +   '<Style ss:ID='+q+'header'+q+'><Font ss:Bold='+q+'1'+q+' ss:Color='+q+'#FFFFFF'+q+' ss:FontName='+q+'Calibri'+q+' ss:Size='+q+'11'+q+'/><Interior ss:Color='+q+'#1F4E79'+q+' ss:Pattern='+q+'Solid'+q+'/></Style>'
      + '</Styles>'
      + '<Worksheet ss:Name='+q+'Facturas'+q+'><Table>'+hdr+row+'</Table></Worksheet>'
      + '</Workbook>';
}
return [{ json: { success: true, file: rutaArchivo }, binary: { data: { data: Buffer.from(xml,'utf-8').toString('base64'), mimeType:'application/vnd.ms-excel', fileName:'tabla_excell_facturas.xls', fileExtension:'xls' } } }];

// Extrae adjuntos válidos (pdf, jpg, jpeg, png) del email y devuelve un ítem por cada uno
const validExt = /\.(pdf|jpg|jpeg|png)$/i;
const items = [];
const binaryData = $binary || {};
const emailMeta = {
  subject: $json.subject || '',
  from: ($json.from && $json.from.text) ? $json.from.text : String($json.from || ''),
  date: $json.date || new Date().toISOString()
};
for (const [key, att] of Object.entries(binaryData)) {
  if (!key.startsWith('attachment')) continue;
  const rawName = att.fileName || att.filename || (key + '.bin');
  if (!validExt.test(rawName)) continue;
  // Sanitiza el nombre para evitar path traversal
  const safeName = rawName.replace(/[^a-zA-Z0-9._\-]/g, '_').replace(/^\.+/, '');
  const savePath = '/data/pdf_excell/entrada_n8n_directo/' + safeName;
  items.push({
    json: { fileName: safeName, savePath, ...emailMeta },
    binary: { data: att }
  });
}
if (items.length === 0) return [];
return items;
